    bodyshots_equipped integer NOT NULL,
    legshots_equipped integer NOT NULL,
    kills smallint NOT NULL,
    first_kills smallint NOT NULL,
    kills_0_10m smallint NOT NULL,
    kills_10_20m smallint NOT NULL,
    kills_20_30m smallint NOT NULL,
    kills_30m_plus smallint NOT NULL,
    distance_sum_m real NOT NULL,
    distance_samples smallint NOT NULL,
    CONSTRAINT weapon_stats_side_check CHECK ((side = ANY (ARRAY['attack'::text, 'defense'::text])))
);


--
-- Name: weapons; Type: TABLE; Schema: analytics; Owner: -
--

CREATE TABLE analytics.weapons (
    id smallint NOT NULL,
    uuid text NOT NULL,
    name text NOT NULL,
    category text,
    cost integer,
    is_armor boolean NOT NULL
);


--
-- Name: weapons_id_seq; Type: SEQUENCE; Schema: analytics; Owner: -
--

ALTER TABLE analytics.weapons ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME analytics.weapons_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: zones; Type: TABLE; Schema: analytics; Owner: -
--

CREATE TABLE analytics.zones (
    id integer NOT NULL,
    map_id smallint NOT NULL,
    name text NOT NULL,
    region text NOT NULL,
    super_region text NOT NULL,
    source text NOT NULL,
    anchor_nx real NOT NULL,
    anchor_ny real NOT NULL,
    label_nx real NOT NULL,
    label_ny real NOT NULL,
    area real NOT NULL,
    path_svg text NOT NULL,
    CONSTRAINT zones_source_check CHECK ((source = ANY (ARRAY['callout'::text, 'cluster'::text])))
);


