	(2, 'player', 19, NULL, NULL, 'pressure', 'negative', 2, 'Queda de rendimento sob pressão', 'Depois que a spike é plantada, seu K/D cai para 0,60. No geral ele é 1,18, e a média dos jogadores nessa situação é 1,00.', 0.6, 1, 50, 0.5, false, '{}'),
	(3, 'player', 24, NULL, NULL, 'pressure', 'positive', 1, 'Bom em situações de clutch', 'Você venceu 5 de 16 rounds em que ficou sozinho contra o adversário (31%). A média é 14%.', 0.3125, 0.13636364, 16, 0.533, false, '{}'),
	(4, 'player', 6, NULL, NULL, 'ability_estimate', 'negative', 1, 'Ultimates em rounds já decididos', '4 dos 8 abates com ultimate aconteceram em rounds que já estavam praticamente ganhos ou perdidos. Guardar a ultimate para um round disputado rende mais. Esta é uma estimativa.', 0.5, NULL, 8, 0.4, true, '{}'),
	(5, 'team', 3, 1, NULL, 'combo', 'positive', 1, 'Dupla que funciona', 'No Ascent, quando andre ajuda e greiN finaliza, o time domina o site em 100% das 10 vezes, contra 89% nas outras jogadas do time. Esta é uma estimativa.', 1, 0.8875, 10, 0.25, true, '{}'),
	(6, 'team', 3, 1, 'attack', 'strategy', 'positive', 1, 'Estratégia que mais funciona', 'No Ascent, no ataque, "Ataque dividido entre A e B pelo Principal B" é a estratégia que mais deu certo para o time: 71% de vitória em 21 rounds.', 0.71428573, NULL, 21, 0.7, false, '{312,317,320,416,500,503,602,604}'),
	(7, 'player', 6, 1, NULL, 'agent', 'positive', 1, 'Seu melhor agente no Ascent', 'Com Jett no Ascent você tem média de 235 de pontuação por round em 5 partidas. A média do agente nesse mapa é 187.', 235.30107, 186.70175, 5, 0.5, false, '{}'),
	(8, 'player', 15, 1, NULL, 'agent', 'positive', 1, 'Seu melhor agente no Ascent', 'Com Sova no Ascent você tem média de 272 de pontuação por round em 5 partidas. A média do agente nesse mapa é 221.', 272.05377, 221.13637, 5, 0.5, false, '{}'),
	(9, 'player', 19, 1, NULL, 'agent', 'positive', 1, 'Seu melhor agente no Ascent', 'Com Cypher no Ascent você tem média de 195 de pontuação por round em 5 partidas. A média do agente nesse mapa é 191.', 195.04301, 191.25, 5, 0.5, false, '{}'),
	(10, 'player', 24, 1, NULL, 'agent', 'positive', 1, 'Seu melhor agente no Ascent', 'Com Phoenix no Ascent você tem média de 284 de pontuação por round em 5 partidas. A média do agente nesse mapa é 239.', 283.86023, 239.44286, 5, 0.5, false, '{}'),
	(11, 'player', 10, NULL, NULL, 'summary', 'positive', 1, 'Seu ponto mais forte', 'Seu ponto mais forte: participação nos rounds (KAST), com 79%. A média dos jogadores é 71%.', 0.7906977, 0.70988375, 9, 0.9, false, '{}');
